const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const mode=document.querySelector('.mode');
mode.addEventListener('click',()=>{const night=document.body.classList.toggle('night');mode.setAttribute('aria-pressed',String(night));mode.setAttribute('aria-label',night?'Revenir à la lumière du jour':'Passer en ambiance nocturne');mode.querySelector('span').textContent=night?'☼':'☾';mode.querySelector('.mode-label').textContent=night?'Au lever du jour':'À la nuit tombée';});
const places={giza:{title:'Face à l’éternité',note:'Gizeh · Le désert des origines',text:'Au bord du désert, les pyramides découpent l’horizon. Leur géométrie semble simple ; leur présence, elle, échappe aux mots. Ici, prenez le temps de regarder la lumière glisser sur la pierre.',extra:'L’escale imaginée : arriver quand les ombres s’allongent, marcher au rythme du sable et observer le plateau changer de couleur.',image:'egypt',pos:'75% center'},nile:{title:'Le temps d’un fleuve',note:'Le Nil · Au rythme de l’eau',text:'Une rive verte, une voile claire et, derrière elles, le désert. Le Nil donne à l’Égypte son rythme et ses contrastes. En suivant son cours, le regard apprend à ralentir.',extra:'L’escale imaginée : embarquer sur une felouque, laisser le vent choisir l’allure et regarder les palmiers dessiner la rive.',image:'temple',pos:'15% 70%'},luxor:{title:'La mémoire des pierres',note:'Louxor · Au seuil des temples',text:'Des colonnes qui semblent toucher le ciel, des murs couverts de signes, des cours ouvertes sur la lumière : à Louxor, chaque seuil invite à regarder autrement.',extra:'L’escale imaginée : entrer dans un temple, chercher les détails gravés dans la pierre et laisser les perspectives vous surprendre.',image:'temple',pos:'75% center'},khepri:{title:'Le soleil recommence',note:'Khépri · Un symbole de renouveau',text:'Associé au scarabée et au soleil levant, Khépri évoque la transformation et le recommencement dans la mythologie égyptienne.',extra:'Nous avons choisi ce nom comme une invitation à retrouver la curiosité du premier voyage. Les paysages de cette expérience sont des créations artistiques inspirées de l’Égypte, et non des reconstitutions archéologiques.',image:'egypt',pos:'85% top'},about:{title:'Une Égypte imaginée',note:'À propos de cette expérience',text:'Khépri est un concept de site immersif créé autour de l’Égypte. Ses illustrations originales ont été générées avec ChatGPT, puis intégrées à une expérience web animée.',extra:'Les escales sont des invitations éditoriales, sans offre de voyage ni réservation. Les scènes prennent des libertés artistiques avec la géographie et les monuments.',image:'temple',pos:'center'}};
const dialog=document.querySelector('dialog');dialog.setAttribute('aria-labelledby','detail-title');let opener;
function openPlace(key,trigger){const p=places[key];opener=trigger;document.querySelector('#detail-title').textContent=p.title;document.querySelector('#detail-note').textContent=p.note;document.querySelector('#detail-text').textContent=p.text;document.querySelector('#detail-extra').textContent=p.extra;const art=document.querySelector('.dialog-image');art.style.backgroundImage=`url(assets/${p.image}.jpg)`;art.style.backgroundPosition=p.pos;dialog.showModal();document.body.style.overflow='hidden';}
document.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>openPlace(b.dataset.place,b)));document.querySelector('#about').addEventListener('click',e=>openPlace('about',e.currentTarget));document.querySelectorAll('.close,.close-bottom').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus();});
const landscape=document.querySelector('.landscape');let scrollY=0,mouseX=0,mouseY=0;window.addEventListener('scroll',()=>{scrollY=window.scrollY;},{passive:true});document.querySelector('.hero').addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){mouseX=(e.clientX/innerWidth-.5)*12;mouseY=(e.clientY/innerHeight-.5)*8;}});
const canvas=document.querySelector('#dust'),ctx=canvas.getContext('2d');let w,h,particles=[];function resize(){w=canvas.width=canvas.clientWidth;h=canvas.height=canvas.clientHeight;particles=Array.from({length:40},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.4+.3,v:Math.random()*.25+.08}));}resize();window.addEventListener('resize',resize);let last=0;function animate(now){if(!reduce.matches&&scrollY<h&&now-last>28){last=now;landscape.style.transform=`translate3d(${mouseX}px,${scrollY*.15+mouseY}px,0) scale(1.025)`;ctx.clearRect(0,0,w,h);const night=document.body.classList.contains('night');particles.forEach(p=>{p.x+=p.v;p.y-=p.v*.2;if(p.x>w)p.x=0;if(p.y<0)p.y=h;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=night?'rgba(255,240,195,.65)':'rgba(255,237,187,.5)';ctx.fill();});}requestAnimationFrame(animate);}requestAnimationFrame(animate);
